-- ==================================================================
-- Baseline table (msoc <runid>_baseline_1), as SAS builds it in
-- ms_createdistbaselinetable.sas.
--
-- ANALYTICS in long form: baseline_long holds one row per cohort x
-- statistic, built by the small static statements below. The WIDE
-- table SAS delivers is a presentation step at the end (two PIVOTs).
-- Nothing here is generated by Python.
--
-- SAS's rules:
--   * demographics (Sex_, Race_, Hispanic_) count each PATIENT once, from
--     their first episode: SAS blanks the indicators on later episodes
--     (lines 437-449). Age bands, years, covariates and every mean/SD
--     are per EPISODE.
--   * levels are DECLARED, not read from the data: Sex F/M/O, Race 0-5/M,
--     Hispanic Y/N/U (ms_adjustedbaselinetables.sas:248-250); age bands
--     from the cohort file's agestrat, named AGE<band> with '-' -> '_'
--     and ' <>+' removed (lines 121-130). Absent levels are 0
--     ("squaring"). An observed value outside a declared list is still
--     reported, as its own column, and warned about by the pipeline.
--   * means and SDs are not rounded; SD is the sample SD.
-- Only cohorts with createbaseline = Y. {util_rel} and {risk_rel} are the
-- utilization and risk-score tables, or empty typed relations when those
-- optional stages did not run (the same convention as the read_ placeholders).
-- ==================================================================
CREATE OR REPLACE TEMP TABLE _bl_ep AS
SELECT c.cohortgrp, c.patid, c.indexdt, c.age, c.agegroup,
       c.sex, c.race, c.hispanic, year(c.indexdt) AS yr,
       row_number() OVER (PARTITION BY c.cohortgrp, c.patid
                          ORDER BY c.indexdt) = 1 AS first_ep
FROM cohort_final c
WHERE c.cohortgrp IN (SELECT cohortgrp FROM cfg_cohort WHERE create_baseline);

CREATE OR REPLACE TABLE baseline_long (
    cohortgrp VARCHAR, stat VARCHAR, kind VARCHAR, n BIGINT, v DOUBLE);

-- patient and episode counts
INSERT INTO baseline_long
SELECT cohortgrp, 'patient', 'count', count(DISTINCT patid), NULL FROM _bl_ep GROUP BY 1
UNION ALL
SELECT cohortgrp, 'n_episodes', 'count', count(*), NULL FROM _bl_ep GROUP BY 1;

-- demographics: declared levels, first episode per patient
INSERT INTO baseline_long
WITH lvl(var, level) AS (VALUES
        ('Sex', 'F'), ('Sex', 'M'), ('Sex', 'O'),
        ('Race', '0'), ('Race', '1'), ('Race', '2'), ('Race', '3'),
        ('Race', '4'), ('Race', '5'), ('Race', 'M'),
        ('Hispanic', 'Y'), ('Hispanic', 'N'), ('Hispanic', 'U')),
demo AS (
    SELECT cohortgrp, 'Sex' AS var, sex AS level FROM _bl_ep WHERE first_ep
    UNION ALL SELECT cohortgrp, 'Race', race FROM _bl_ep WHERE first_ep
    UNION ALL SELECT cohortgrp, 'Hispanic', hispanic FROM _bl_ep WHERE first_ep
),
counted AS (SELECT cohortgrp, var, level, count(*) AS n FROM demo
            WHERE level IS NOT NULL GROUP BY ALL)
SELECT g.cohortgrp, l.var || '_' || l.level, 'count', coalesce(d.n, 0), NULL
FROM (SELECT DISTINCT cohortgrp FROM _bl_ep) g
CROSS JOIN lvl l
LEFT JOIN counted d ON d.cohortgrp = g.cohortgrp AND d.var = l.var AND d.level = l.level
UNION ALL
-- observed values outside the declared lists: kept, not silently dropped
SELECT d.cohortgrp, d.var || '_' || regexp_replace(d.level, '[^A-Za-z0-9]', '_', 'g'),
       'undeclared', d.n, NULL
FROM counted d
WHERE NOT EXISTS (SELECT 1 FROM lvl l WHERE l.var = d.var AND l.level = d.level);

-- age bands (declared from agestrat) and index years, per episode.
-- Counted with GROUP BY and joined to the declared levels: no correlated
-- subquery per cohort x level (a lookup per row was a past performance
-- bug in this table).
INSERT INTO baseline_long
WITH grp AS (SELECT DISTINCT cohortgrp FROM _bl_ep),
     bands AS (SELECT DISTINCT label FROM cfg_age_strata),
     -- Every year of the query period, plus any observed index year. SAS
     -- takes years from its baseline input (_RawData, line 136); on wp307
     -- its columns were exactly 2016-2025 for a 2016-04-01..2025-04-30
     -- period, with Year_2025 0 in every cohort and no 2025 index date.
     -- INFERRED from that run, not traced through SAS's source.
     yrs AS (SELECT DISTINCT y AS yr FROM (
                 SELECT unnest(range(year(DATE '{start_date}'),
                                     year(DATE '{end_date}') + 1)) AS y
                 UNION SELECT yr FROM _bl_ep)),
     band_n AS (SELECT cohortgrp, agegroup, count(*) AS n FROM _bl_ep GROUP BY 1, 2),
     year_n AS (SELECT cohortgrp, yr, count(*) AS n FROM _bl_ep GROUP BY 1, 2)
SELECT g.cohortgrp,
       'AGE' || upper(regexp_replace(replace(b.label, '-', '_'), '[ <>+]', '', 'g')),
       'count', coalesce(n.n, 0), NULL
FROM grp g CROSS JOIN bands b
LEFT JOIN band_n n ON n.cohortgrp = g.cohortgrp AND n.agegroup = b.label
UNION ALL
SELECT g.cohortgrp, 'Year_' || y.yr, 'count', coalesce(n.n, 0), NULL
FROM grp g CROSS JOIN yrs y
LEFT JOIN year_n n ON n.cohortgrp = g.cohortgrp AND n.yr = y.yr;

-- covariates: episodes with each covariate (same pattern, no correlation)
INSERT INTO baseline_long
WITH grp AS (SELECT DISTINCT cohortgrp FROM _bl_ep),
     covs AS (SELECT DISTINCT covarnum FROM cfg_covariate_codes),
     cov_n AS (SELECT cohortgrp, covarnum, count(*) AS n
               FROM (SELECT DISTINCT cohortgrp, covarnum, patid, indexdt FROM covariates_long)
               GROUP BY 1, 2)
SELECT g.cohortgrp, 'covar' || k.covarnum, 'count', coalesce(n.n, 0), NULL
FROM grp g CROSS JOIN covs k
LEFT JOIN cov_n n ON n.cohortgrp = g.cohortgrp AND n.covarnum = k.covarnum;

-- means and sample SDs, per episode, unrounded: age, utilization
INSERT INTO baseline_long
WITH vals AS (
    UNPIVOT (
        SELECT e.cohortgrp, e.age AS "age",
               u.enc_av AS "NumAV", u.enc_oa AS "NumOA", u.enc_ip AS "NumIP",
               u.enc_is AS "NumIS", u.enc_ed AS "NumED",
               u.numgeneric AS "NumGeneric", u.numclass AS "NumClass", u.numrx AS "NumRx"
        FROM _bl_ep e
        LEFT JOIN {util_rel} u
          ON u.cohortgrp = e.cohortgrp AND u.patid = e.patid AND u.indexdt = e.indexdt
    ) ON COLUMNS(* EXCLUDE (cohortgrp)) INTO NAME name VALUE x
)
SELECT cohortgrp, 'mean_' || name, 'stat', NULL, avg(x) FROM vals GROUP BY cohortgrp, name
UNION ALL
SELECT cohortgrp, 'std_' || name, 'stat', NULL, stddev_samp(x) FROM vals GROUP BY cohortgrp, name;

-- risk scores (e.g. CCI), per episode
INSERT INTO baseline_long
SELECT e.cohortgrp, s || r.riskscore, 'stat', NULL,
       CASE s WHEN 'mean_' THEN avg(r.score) ELSE stddev_samp(r.score) END
FROM _bl_ep e
JOIN {risk_rel} r ON r.cohortgrp = e.cohortgrp AND r.patid = e.patid AND r.indexdt = e.indexdt
CROSS JOIN (VALUES ('mean_'), ('std_')) t(s)
GROUP BY e.cohortgrp, s, r.riskscore;

-- ------------------------------------------------------------------
-- PRESENTATION: SAS's wide layout, one row per cohort.
-- ------------------------------------------------------------------
CREATE OR REPLACE TABLE baseline AS
SELECT *
FROM (PIVOT (SELECT cohortgrp AS "group", stat, n FROM baseline_long WHERE kind <> 'stat')
      ON stat USING sum(n)::BIGINT GROUP BY "group") c
LEFT JOIN (PIVOT (SELECT cohortgrp AS "group", stat, v FROM baseline_long WHERE kind = 'stat')
           ON stat USING first(v) GROUP BY "group") s USING ("group")
ORDER BY 1;
